// Main-only commit and exact-source seal. Never installs or publishes the Atlas.
import fs from 'node:fs';import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';import {hash,json} from './seal-simple-website-successor.mjs';
const stage='F:/VisibleMedicine/staging/20261023-upper-cervical-reasoning',atlas=stage+'/atlas',prepared=json(stage+'/PREPARED.json');
const git=(...args)=>execFileSync('git',['-C',atlas,...args],{encoding:'utf8',windowsHide:true,maxBuffer:32e6}).trim();assert.equal(git('rev-parse','HEAD'),prepared.head);
const expected=['LICENSES/THIRD_PARTY_NOTICES.md','content/body-renderer-revision.json','content/body-review-display-pins.json','docs/CURRENT_STATUS.md','docs/REASONING_PRACTICE.md','docs/reasoning-practice-validation.json','docs/requirement-audit.json','lib/reasoning-questions.ts','package.json','scripts/validate-reasoning-practice.mjs','content/upper-cervical-reasoning-pins.json','docs/UPPER_CERVICAL_REASONING.md','lib/upper-cervical-reasoning.ts','scripts/check-upper-cervical-types.mjs','scripts/pin-upper-cervical-reasoning.mjs','scripts/test-upper-cervical-reasoning.mjs'];
const changed=git('diff','--name-only').split('\n').filter(Boolean),added=git('ls-files','--others','--exclude-standard').split('\n').filter(Boolean);assert.deepEqual(new Set([...changed,...added]),new Set(expected));
for(const r of prepared.files){assert.equal(hash(prepared.parent+'/'+r.path),r.sha256);if(!changed.includes(r.path))assert.equal(hash(atlas+'/'+r.path),r.sha256,'Unexpected source drift '+r.path);}
const phases=['pins','display','native','native-v2','practice-v2','types','snapshot','regional','holds','requirements','requirements-check','build','renderer-check'];
const checks=phases.map(p=>{const dir=stage+'/checks/'+p,t=json(dir+'/TERMINAL.json');assert.equal(t.code,0,p);assert.equal(hash(dir+'/stdout.log'),t.stdoutSha256);assert.equal(hash(dir+'/stderr.log'),t.stderrSha256);return t;});
const first=json(stage+'/checks/practice/TERMINAL.json');assert.equal(first.code,1);assert.equal(hash(stage+'/checks/practice/stderr.log'),first.stderrSha256);
const migration=json(stage+'/MIGRATION.json');assert(migration.wholeForwardAndInverse&&migration.packageScriptOnly&&migration.dependenciesUnchanged);
const preservation=json(stage+'/PRESERVATION.json');assert.equal(preservation.changedTeachingWorksheets,8);assert.equal(preservation.unchangedTeachingWorksheets,1096);assert.equal(preservation.priorConceptsPreserved,193);assert.equal(preservation.priorSessionsPreserved,346);assert.equal(preservation.unchangedTopicPlacements,9936);
const validation=json(atlas+'/docs/reasoning-practice-validation.json');assert.equal(validation.concepts,197);assert.equal(validation.exactRepresentations,354);assert.equal(validation.checks,22758);assert.equal(validation.negativeIdentityCases,5563);
const native=JSON.parse(fs.readFileSync(stage+'/checks/native-v2/stdout.log','utf8').trim().split(/\r?\n/).at(-1));assert.equal(native.identityNegatives,280);assert.equal(native.practicePaths,48);assert.equal(native.packetNegatives,40);assert.equal(native.stalePosts,8);
const types=JSON.parse(fs.readFileSync(stage+'/checks/types/stdout.log','utf8').trim().split(/\r?\n/).at(-1));assert.equal(types.diagnostics,0);assert.equal(types.sourceFiles,593);
const oldPins=JSON.parse(execFileSync('git',['-C',atlas,'show',prepared.head+':content/body-review-display-pins.json'],{encoding:'utf8',maxBuffer:32e6})),newPins=json(atlas+'/content/body-review-display-pins.json');assert.equal(newPins.pins.length,1104);
const newIds=json(atlas+'/content/upper-cervical-reasoning-pins.json').entries.map(e=>e.identity.id).sort(),changedPins=[];for(const p of newPins.pins){const before=oldPins.pins.find(b=>b.structureId===p.structureId);assert(before);if(before.sha256!==p.sha256)changedPins.push(p.structureId);}assert.deepEqual(changedPins.sort(),newIds);
const files=[];function walk(dir,prefix=''){for(const e of fs.readdirSync(dir,{withFileTypes:true})){assert(!e.isSymbolicLink());if(e.isDirectory())walk(dir+'/'+e.name,prefix+e.name+'/');else files.push({path:prefix+e.name,bytes:fs.statSync(dir+'/'+e.name).size,sha256:hash(dir+'/'+e.name)});}}walk(atlas+'/dist');files.sort((a,b)=>a.path.localeCompare(b.path));
const candidate=json(stage+'/candidate-snapshot.json'),concepts=candidate.concepts.slice(193);
const emitted=files.filter(r=>r.path.startsWith('client/')&&r.path.endsWith('.js')).filter(r=>{const s=fs.readFileSync(atlas+'/dist/'+r.path,'utf8');return s.includes('upper-cervical-')&&concepts.every(c=>s.includes(c.prompt));});assert(emitted.length>0,'Actual emitted learner delivery must contain all4question stems and the source-bound prefix');
fs.writeFileSync(stage+'/BUILD_ARTIFACTS.json',JSON.stringify({at:new Date().toISOString(),files,emittedQuestionFiles:emitted},null,2)+'\n',{flag:'wx'});
fs.writeFileSync(stage+'/SOURCE_DIFF.patch',git('diff','--no-ext-diff')+'\n',{flag:'wx'});
assert.equal(json('CURRENT_CHECKPOINT.json').activeWork.current.ownerPreviewPolicy.restartPermitted,false);
git('add','--',...expected);git('commit','-m','Add source-bound upper cervical reasoning drafts');assert.equal(git('status','--porcelain'),'');
const sourceRows=git('ls-files','-z').split('\0').filter(Boolean).map(p=>({path:p,bytes:fs.statSync(atlas+'/'+p).size,sha256:hash(atlas+'/'+p)}));
const receipt={at:new Date().toISOString(),atlas,head:git('rev-parse','HEAD'),tree:git('rev-parse','HEAD^{tree}'),parent:prepared.head,parentTree:prepared.tree,changed,added,sourceRows,sourcePaths:sourceRows.length,checks,
 buildArtifacts:stage+'/BUILD_ARTIFACTS.json',buildArtifactsSha256:hash(stage+'/BUILD_ARTIFACTS.json'),buildFiles:files.length,emittedQuestionFiles:emitted,
 preservation:stage+'/PRESERVATION.json',preservationSha256:hash(stage+'/PRESERVATION.json'),migration:stage+'/MIGRATION.json',migrationSha256:hash(stage+'/MIGRATION.json'),
 concepts:197,sourceSelections:354,newDraftConcepts:4,newSourceSelections:8,previousConceptsAndSessionsPreserved:true,combinedPracticeChecks:22758,negativeIdentityChecks:5563,newIdentityMutationsRejected:280,newPracticePaths:48,tamperedPacketsRefused:40,stalePostsRefusedBeforeStorage:8,focusedTypeFiles:593,focusedTypeDiagnostics:0,
 completeAtlasBuildPassed:true,modelAssetsDependenciesAndSourceHoldsUnchanged:true,privateDecisionsReadOrMigrated:false,websiteIntegrationPending:true,latestFullWebsiteCandidate:'F:/VisibleMedicine/staging/20261023-linked-menus-website/SOURCE_BOUND.json',previewChanged:false,installed:false,clinicalApproval:false,patientSpaceRegistration:false,wholeSuitePassing:false};
fs.writeFileSync(stage+'/SOURCE_BOUND.json',JSON.stringify(receipt,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({receipt:stage+'/SOURCE_BOUND.json',sha256:hash(stage+'/SOURCE_BOUND.json'),head:receipt.head,tree:receipt.tree,sourcePaths:sourceRows.length,buildFiles:files.length}));
